-- Saját ERP: tényleges szerzőnevek a bejegyzésben és döntési naplóban. Jogosultság változatlan.
begin;
create or replace function public.erp_entry_read(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_entry uuid default null,p_version bigint default null,p_archived boolean default false,p_before timestamptz default null,p_before_id uuid default null,p_event_before timestamptz default null,p_event_before_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ctx jsonb;g erp.garden_projects;q erp.quote_versions;e erp.project_entries;v erp.project_entry_versions;result jsonb;last_entry jsonb;last_event jsonb;begin
 ctx:=erp_private.entry_scope(p_actor,p_session,p_project,p_role,p_entry);select * into g from erp.garden_projects where id=p_project;
 select * into q from erp.quote_versions where organization_id=g.organization_id and quote_id=g.accepted_quote_id and version=g.accepted_quote_version;
 if p_entry is not null then select * into e from erp.project_entries where id=p_entry;select * into v from erp.project_entry_versions where entry_id=p_entry and version=coalesce(p_version,e.current_version);if not found then raise exception 'Nincs ilyen bejegyzésváltozat.' using errcode='22023';end if;end if;
 result:=jsonb_build_object('context',ctx,'quote',to_jsonb(q),'book',case when p_role='office' then (select document from erp.price_books where organization_id=g.organization_id) else null end,
 'entries',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'kind',x.kind,'state',x.state,'revision',x.revision,'version',x.current_version,'archived',x.archived,'author_id',x.author_id,'author_role',x.author_role,'author_name',(select p.display_name from erp.persons p where p.id=x.author_id and p.organization_id=x.organization_id),'visible_to_team',x.visible_to_team,'recipient_id',x.recipient_id,'created_at',x.created_at,'updated_at',x.updated_at,'body',left(ev.payload->>'body',180)) order by x.updated_at desc,x.id desc) from (select * from erp.project_entries a where a.organization_id=g.organization_id and a.project_id=p_project and (p_archived or not a.archived) and (p_before is null or (a.updated_at,a.id)<(p_before,p_before_id)) and (p_role in('office','client') or a.visible_to_team or a.author_id=(ctx->>'person_id')::uuid or a.recipient_id=(ctx->>'person_id')::uuid) order by a.updated_at desc,a.id desc limit 100)x join erp.project_entry_versions ev on ev.entry_id=x.id and ev.version=x.current_version),'[]'),
 'entry',case when e.id is null then null else to_jsonb(e)||jsonb_build_object('author_name',(select p.display_name from erp.persons p where p.id=e.author_id and p.organization_id=e.organization_id),'version',to_jsonb(v),'base_quote',(select to_jsonb(b) from erp.quote_versions b where b.organization_id=g.organization_id and b.quote_id=g.accepted_quote_id and b.version=v.base_quote_version),
 'decisions',coalesce((select jsonb_agg(to_jsonb(d)||jsonb_build_object('actor_name',(select p.display_name from erp.persons p where p.id=d.actor_id and p.organization_id=d.organization_id)) order by d.created_at) from erp.project_entry_decisions d where d.entry_id=e.id and d.version=v.version),'[]'),
 'versions',coalesce((select jsonb_agg(jsonb_build_object('version',a.version,'created_at',a.created_at,'actor_id',a.actor_id,'actor_role',a.actor_role,'actor_name',(select p.display_name from erp.persons p where p.id=a.actor_id and p.organization_id=a.organization_id),'offer_summary',a.offer_summary,'base_quote_version',a.base_quote_version) order by a.version desc) from erp.project_entry_versions a where a.entry_id=e.id),'[]'),
 'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id desc) from(select z.id,z.version,z.actor_id,z.active_role,z.kind,z.data,z.created_at,(select p.display_name from erp.persons p where p.id=z.actor_id and p.organization_id=z.organization_id) as actor_name from erp.project_entry_events z where z.entry_id=e.id and (p_event_before is null or (z.created_at,z.id)<(p_event_before,p_event_before_id)) order by z.created_at desc,z.id desc limit 100)x),'[]')) end);
last_entry:=(result->'entries')->-1;last_event:=(result->'entry'->'events')->-1;
 result:=result||jsonb_build_object('entry_cursor',case when jsonb_array_length(result->'entries')=100 then jsonb_build_object('time',last_entry->>'updated_at','id',last_entry->>'id') else null end);
 if e.id is not null then result:=jsonb_set(result,'{entry,event_cursor}',case when jsonb_array_length(result->'entry'->'events')=100 then jsonb_build_object('time',last_event->>'created_at','id',last_event->>'id') else 'null'::jsonb end);end if;
 return result;
end$$;

commit;
